// Zen prefs for the bloom style, read on every start. Generated by facet theme from
// themes/<theme>.json; edit templates/bloom/zen/user.js instead.

// Load chrome/userChrome.css (off by default)
user_pref("toolkit.legacyUserProfileCustomizations.stylesheets", true);

// facet bloom ({{name}}): the accent, dark windows, round panels with gaps like bloom's
user_pref("zen.theme.accent-color", "{{tones.primary}}");
user_pref("zen.view.window.scheme", 0);
user_pref("zen.theme.border-radius", 18);
user_pref("zen.theme.content-element-separation", 8);

// The facet start page (templates/bloom/zen/startpage.html) as the home page and on
// start; facet install zen links it to ~/.local/share/frameshell/startpage.html
user_pref("browser.startup.homepage", "file://{{home}}/.local/share/frameshell/startpage.html");
user_pref("browser.startup.page", 1);

user_pref("zen.welcome-screen.seen", true);
user_pref("zen.watermark.enabled", false);
